#include <bits/stdc++.h>
using namespace std;

struct Vec2 {
    int x, y;
    Vec2(int x, int y) { this->x = x; this->y = y; }
    Vec2& operator+=(const Vec2& o) { x += o.x; this->y += o.y; return *this; }
    Vec2& operator-=(const Vec2& o) {
        if (this == &o) { x = 0; y = 0; return *this; }
        this->x -= o.x; y -= o.y; return *this;
    }
    Vec2& scale(int k) { this->x *= k; y *= k; return *this; }
    int dot(const Vec2& o) const { return this->x * o.x + y * o.y; }
    void print() const { cout << "(" << x << ", " << this->y << ")" << endl; }
};

int main() {
    Vec2 a(1, 2), b(3, -4);
    a += b;
    a.print();
    a += a;
    a.print();
    (a -= b).scale(2).print();
    b -= b;
    b.print();
    Vec2 c(2, 3);
    for (int i = 0; i < 3; i++) {
        c += Vec2(i, -i);
        if (c.dot(c) % 2 == 0) c.scale(-1);
        c.print();
    }
    cout << a.dot(c) << endl;
    return 0;
}

