class IntBuffer {
private:
    int* data;
    int size;
public:
    IntBuffer(int size) {
        this->size = size;
        data = new int[size];
        for (int i = 0; i < size; i++) this->data[i] = i * i;
    }
    IntBuffer(const IntBuffer& other) : data(new int[other.size]), size(other.size) {
        for (int i = 0; i < size; i++) data[i] = other.data[i];
    }
    ~IntBuffer() { delete[] data; }
    IntBuffer& operator=(const IntBuffer& other) {
        if (this == &other) {
            cout << "self-assign skipped" << endl;
            return *this;
        }
        delete[] this->data;
        this->size = other.size;
        data = new int[size];
        for (int i = 0; i < this->size; i++) data[i] = other.data[i];
        return *this;
    }
    void set(int i, int v) { if (i >= 0 && i < size) this->data[i] = v; }
    int sum() const {
        int s = 0;
        for (int i = 0; i < this->size; i++) s += data[i];
        return s;
    }
    void print() const {
        cout << "[";
        for (int i = 0; i < size; i++) {
            if (i) cout << ",";
            cout << this->data[i];
        }
        cout << "] sum=" << this->sum() << endl;
    }
};

int main() {
    IntBuffer a(5), b(3);
    a.print();
    b.print();
    b = a;
    b.set(0, 100);
    a.print();
    b.print();
    IntBuffer& ref = a;
    a = ref;
    a.print();
    IntBuffer c(2);
    c = b = a;
    c.print();
    IntBuffer d(c);
    d.set(4, -1);
    d.print();
    c.print();
    return 0;
}

