class Pizza {
    string size;
    int cheese;
    vector<string> toppings;
    double price;
public:
    Pizza() : size("medium"), cheese(1), price(0) {}
    Pizza& setSize(const string& size) { this->size = size; return *this; }
    Pizza& setCheese(int cheese) {
        if (cheese < 0) cheese = 0;
        this->cheese = cheese;
        return *this;
    }
    Pizza& addTopping(string t) { toppings.push_back(t); return *this; }
    Pizza& computePrice() {
        double base = 8.0;
        if (this->size == "small") base = 6.0;
        else if (size == "large") base = 11.0;
        price = base + this->cheese * 1.5 + toppings.size() * 0.75;
        return *this;
    }
    void describe() const {
        cout << size << " pizza, cheese x" << this->cheese << ", toppings:";
        for (const auto& t : this->toppings) cout << " " << t;
        cout << fixed << setprecision(2) << " => $" << price << endl;
    }
};

int main() {
    Pizza p;
    p.setSize("large").setCheese(2).addTopping("ham").addTopping("olive").computePrice().describe();
    Pizza q;
    q.setCheese(-3).computePrice();
    q.describe();
    vector<string> names = {"small", "medium", "large"};
    for (int i = 0; i < 3; i++) {
        Pizza r;
        r.setSize(names[i]).setCheese(i);
        for (int j = 0; j <= i; j++) r.addTopping("t" + to_string(j));
        r.computePrice().describe();
    }
    return 0;
}

