class Account;
void report(const Account& a);

class Account {
public:
    string owner;
    int balance;
    Account(string owner, int balance) : owner(owner), balance(balance) {}
    bool transfer(Account& to, int amount) {
        if (this == &to) {
            cout << owner << ": cannot transfer to self" << endl;
            return false;
        }
        if (amount > this->balance) {
            cout << owner << ": insufficient funds" << endl;
            return false;
        }
        this->balance -= amount;
        to.balance += amount;
        report(*this);
        report(to);
        return true;
    }
    bool isRicherThan(const Account* other) const {
        if (other == this) return false;
        return balance > other->balance;
    }
};

void report(const Account& a) {
    cout << "  " << a.owner << " has " << a.balance << endl;
}

int main() {
    Account alice("Alice", 100), bob("Bob", 50);
    alice.transfer(bob, 30);
    bob.transfer(bob, 10);
    bob.transfer(alice, 500);
    vector<Account*> all = {&alice, &bob};
    for (int round = 0; round < 3; round++) {
        Account* from = all[round % 2];
        Account* to = all[(round + 1) % 2];
        from->transfer(*to, 15 * (round + 1));
    }
    cout << boolalpha << alice.isRicherThan(&bob) << " " << bob.isRicherThan(&alice)
         << " " << alice.isRicherThan(&alice) << endl;
    return 0;
}

