class Thermostat {
    int target;
    int current;
    int steps;
    bool heating() const { return this->current < target; }
    void stepOnce() {
        if (this->heating()) current++;
        else if (current > this->target) this->current--;
        steps++;
    }
public:
    Thermostat(int current, int target) {
        this->current = current;
        this->target = target;
        steps = 0;
    }
    int run(int maxSteps) {
        int target = this->target + 1;  // local shadows member
        while (this->current != this->target && steps < maxSteps) {
            this->stepOnce();
        }
        return target + steps;
    }
    void retarget(int target) {
        if (target == this->target) {
            cout << "same target " << target << endl;
            return;
        }
        this->target = target;
        steps = 0;
    }
    void show() const {
        cout << "current=" << current << " target=" << this->target
             << " steps=" << steps << (this->heating() ? " heating" : " idle") << endl;
    }
};

int main() {
    Thermostat t(18, 22);
    cout << t.run(10) << endl;
    t.show();
    t.retarget(22);
    t.retarget(15);
    cout << t.run(3) << endl;
    t.show();
    cout << t.run(10) << endl;
    t.show();
    return 0;
}

