struct Node;
vector<Node*> registry;
void enroll(Node* n) { registry.push_back(n); }

struct Node {
    int value;
    Node* next;
    Node(int value) : value(value), next(nullptr) { enroll(this); }
    Node& link(Node& other) {
        if (&other == this) {
            cout << "refuse self-link at " << value << endl;
            return *this;
        }
        this->next = &other;
        return other;
    }
    int lengthFromHere() const {
        int len = 0;
        const Node* cur = this;
        while (cur != nullptr && len < 100) { len++; cur = cur->next; }
        return len;
    }
    int sumFromHere() const {
        return value + (this->next ? this->next->sumFromHere() : 0);
    }
};

int main() {
    Node a(1), b(2), c(3), d(4);
    a.link(b).link(c).link(d);
    d.link(d);
    cout << a.lengthFromHere() << " " << a.sumFromHere() << endl;
    cout << c.lengthFromHere() << " " << c.sumFromHere() << endl;
    for (size_t i = 0; i < registry.size(); i++) {
        Node* n = registry[i];
        cout << n->value << (n->next ? "->" + to_string(n->next->value) : string("->null"));
        if (n == &b) cout << " (b)";
        cout << endl;
    }
    return 0;
}

