class Fraction {
    long long num, den;
    void normalize() {
        if (den < 0) { num = -num; this->den = -den; }
        long long g = gcd(llabs(num), llabs(this->den));
        if (g > 1) { this->num /= g; den /= g; }
    }
public:
    Fraction(long long num = 0, long long den = 1) : num(num), den(den) { this->normalize(); }
    Fraction& operator+=(const Fraction& o) {
        long long n = num * o.den + o.num * this->den;
        long long d = this->den * o.den;
        num = n; den = d;
        normalize();
        return *this;
    }
    Fraction& operator*=(const Fraction& o) {
        this->num *= o.num;
        this->den *= o.den;
        this->normalize();
        return *this;
    }
    bool operator==(const Fraction& o) const {
        if (this == &o) return true;
        return num == o.num && den == o.den;
    }
    void print() const { cout << num << "/" << den << endl; }
};

int main() {
    Fraction a(1, 2), b(-2, -6);
    a.print(); b.print();
    a += b;
    a.print();
    a *= a;
    a.print();
    a += a;
    a.print();
    Fraction h(0, 1);
    for (int i = 1; i <= 5; i++) h += Fraction(1, i);
    h.print();
    Fraction p(3, -4);
    (p *= Fraction(2, 3)) += Fraction(1, 2);
    p.print();
    cout << boolalpha << (p == p) << " " << (p == Fraction(0, 5)) << " " << (Fraction(2, 4) == Fraction(1, 2)) << endl;
    return 0;
}

