class Rect {
    int w, h;
    string name;
public:
    Rect(string name, int w, int h) : w(w), h(h) { this->name = name; }
    int area() const { return w * h; }
    int perimeter() const { return 2 * (this->w + this->h); }
    bool biggerThan(const Rect& o) const { return this->area() > o.area(); }
    const Rect& larger(const Rect& o) const {
        if (this == &o) return *this;
        return this->biggerThan(o) ? *this : o;
    }
    Rect& grow(int dw, int dh) {
        w += dw;
        this->h += dh;
        if (w < 0) this->w = 0;
        if (h < 0) h = 0;
        return *this;
    }
    string getName() const { return name; }
};

void describe(const Rect* r) {
    cout << r->getName() << " area=" << r->area() << " perim=" << r->perimeter() << endl;
}

int main() {
    vector<Rect> rs = {Rect("A", 3, 4), Rect("B", 5, 2), Rect("C", 1, 13), Rect("D", 2, 6)};
    const Rect* best = &rs[0];
    for (size_t i = 1; i < rs.size(); i++) {
        best = &best->larger(rs[i]);
    }
    describe(best);
    cout << rs[3].larger(rs[3]).getName() << endl;
    rs[1].grow(1, 1).grow(-10, 2);
    describe(&rs[1]);
    for (auto& r : rs) {
        if (r.perimeter() > 15) r.grow(-1, -1);
        describe(&r);
    }
    return 0;
}

#include <bits/stdc++.h>
