class IntStack;
void dump(const IntStack& s);

class IntStack {
    int items[16];
    int size;
public:
    IntStack() : size(0) {}
    IntStack& push(int v) {
        if (this->size < 16) items[size++] = v;
        return *this;
    }
    IntStack& pop() {
        if (size > 0) this->size--;
        return *this;
    }
    int top() const { return size > 0 ? this->items[this->size - 1] : -1; }
    int getSize() const { return size; }
    int at(int i) const { return items[i]; }
    IntStack& doubleTop() {
        if (this->size == 0) return *this;
        int size = this->size;
        int v = items[size - 1];
        return this->push(v * 2);
    }
    IntStack& show() { dump(*this); return *this; }
};

void dump(const IntStack& s) {
    cout << "size " << s.getSize() << ":";
    for (int i = 0; i < s.getSize(); i++) cout << " " << s.at(i);
    cout << endl;
}

int main() {
    IntStack s;
    s.push(1).push(2).push(3).show().pop().doubleTop().show();
    for (int i = 0; i < 5; i++) {
        if (s.top() % 3 == 0) s.pop();
        else s.doubleTop();
    }
    s.show();
    IntStack e;
    e.doubleTop().pop().pop().show();
    cout << e.top() << " " << s.top() << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class Poly {
    vector<int> c;
public:
    Poly(vector<int> c) { this->c = c; trim(); }
    void trim() { while (this->c.size() > 1 && c.back() == 0) c.pop_back(); }
    Poly& operator*=(const Poly& o) {
        Poly self = *this;
        vector<int> r(self.c.size() + o.c.size() - 1, 0);
        for (size_t i = 0; i < self.c.size(); i++)
            for (size_t j = 0; j < o.c.size(); j++)
                r[i + j] += self.c[i] * o.c[j];
        this->c = r;
        this->trim();
        return *this;
    }
    Poly& operator+=(const Poly& o) {
        if (o.c.size() > c.size()) this->c.resize(o.c.size(), 0);
        for (size_t i = 0; i < o.c.size(); i++) c[i] += o.c[i];
        trim();
        return *this;
    }
    int eval(int x) const {
        int r = 0;
        for (int i = (int)this->c.size() - 1; i >= 0; i--) r = r * x + c[i];
        return r;
    }
    void print() const {
        bool first = true;
        for (int i = (int)c.size() - 1; i >= 0; i--) {
            if (c[i] == 0 && c.size() > 1) continue;
            if (!first) cout << (c[i] < 0 ? " - " : " + ");
            else if (c[i] < 0) cout << "-";
            cout << abs(c[i]);
            if (i > 0) cout << "x";
            if (i > 1) cout << "^" << i;
            first = false;
        }
        cout << endl;
    }
};

int main() {
    Poly p({1, 1});
    p *= p;
    p.print();
    p *= p;
    p.print();
    Poly q({-1, 0, 2});
    q += Poly({1, 0, -2});
    q.print();
    Poly r({3, -2});
    (r += Poly({0, 2, 1})) *= Poly({1, -1});
    r.print();
    for (int x = -2; x <= 2; x++) cout << r.eval(x) << (x < 2 ? " " : "\n");
    r += r;
    r.print();
    return 0;
}
